import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import useIntl from 'react-intl/src/components/useIntl';

import { useDateTimeRangePickerValidation } from './useDateTimeRangePickerValidation.js';
import type { TimeValue } from '../../../core/types/time.js';
import { isEqualTimeValue } from '../helpers.js';
import type { DateTimeRangePickerProps } from '../types.js';

/**
 * A hook that provides the default functionality for the DateTimeRange picker
 */
export const useDateTimeRangePicker = (
  props: DateTimeRangePickerProps,
  touchedRef: React.RefObject<HTMLElement>,
) => {
  const {
    value,
    defaultValue,
    placeholder,
    readOnly,
    min,
    max,
  }: DateTimeRangePickerProps = props;
  const { formatMessage } = useIntl();

  const [valueFrom, setValueFrom] = useState<TimeValue | null>(
    value?.from ?? defaultValue?.from ?? null,
  );
  const [valueTo, setValueTo] = useState<TimeValue | null>(
    value?.to ?? defaultValue?.to ?? null,
  );

  // hook to handled from and to value states as well as the combined error (e.g. invalid order)
  const { reevaluate, evaluate, onBlurTouched, onError, error } =
    useDateTimeRangePickerValidation(touchedRef, valueFrom, valueTo, {
      min,
      max,
    });

  const firstRun = useRef(true);

  const localizedPlaceholder = useMemo(
    () => ({
      from:
        placeholder?.from ??
        formatMessage({
          defaultMessage: 'Start time',
          id: 'gnKOHMjpyzk6hNcF',
          description: 'Start of timeframe',
        }),
      to:
        placeholder?.to ??
        formatMessage({
          defaultMessage: 'End time',
          id: 'sGxf5yRVhyC8Fpo/',
          description: 'End of timeframe',
        }),
    }),
    [formatMessage, placeholder?.from, placeholder?.to],
  );

  // for non null values, put the from/to value as `<TimeValue>/<TimeValue>` into the clipboard
  const onCopyCapture: React.ClipboardEventHandler = useCallback(
    (event) => {
      if (valueFrom === null || valueTo === null) {
        return;
      }

      navigator.clipboard.writeText(`${valueFrom.value}/${valueTo.value}`);
      event.preventDefault();
      event.stopPropagation();
    },
    [valueFrom, valueTo],
  );

  // clipboard paste handler. apply clipboard content if formatted correctly
  const onPasteCapture: React.ClipboardEventHandler = useCallback(
    (e) => {
      if (readOnly) {
        return;
      }
      const data = e.clipboardData?.getData('text/plain');
      if (!data) {
        return;
      }

      // if the clipboard content is of format `<TimeValue>/<TimeValue>`, apply them.
      const [nextFrom, nextTo] = data
        .trim()
        .split('/')
        .map((input) => evaluate(input));

      if (nextFrom && nextTo) {
        setValueFrom(nextFrom);
        setValueTo(nextTo);
        e.preventDefault();
      }
    },
    [evaluate, readOnly],
  );

  // call onChange prop on from/to value change
  useEffect(() => {
    // Don't call the onChange handler on component mount
    if (firstRun.current) {
      firstRun.current = false;
      return;
    }
    // if both values from & to are null, return null.
    if (valueFrom === null && valueTo === null) {
      props.onChange?.(null);
      return;
    }

    // only fire on change if a from and a to value is available.
    if (valueFrom !== null && valueTo !== null) {
      props.onChange?.({ from: valueFrom, to: valueTo });
      return;
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [valueFrom, valueTo]);

  // update internal from and to state change on prop.value change
  useEffect(() => {
    // ignore if uncontrolled
    if (props.value === undefined) {
      return;
    }

    // update internal states, only fire if value differs
    const nextFrom = props?.value?.from ?? null;
    setValueFrom((prevFrom) =>
      isEqualTimeValue(prevFrom, nextFrom) ? prevFrom : nextFrom,
    );
    const nextTo = props?.value?.to ?? null;
    setValueTo((prevTo) =>
      isEqualTimeValue(prevTo, nextTo) ? prevTo : nextTo,
    );
  }, [props.value]);

  return {
    placeholder: localizedPlaceholder,
    value: {
      from: valueFrom,
      to: valueTo,
    },
    onChange: {
      from: (value) => setValueFrom(reevaluate(value)),
      to: (value) => setValueTo(reevaluate(value)),
    },
    onCopyCaputure: onCopyCapture,
    onPasteCapture,
    onBlurTouched,
    onError,
    error,
  };
};
